    let lumaUpRight = sampleLumaOffset(coords, 1.0, 1.0);
    let lumaUpLeft = sampleLumaOffset(coords, -1.0, 1.0);
    let lumaDownRight = sampleLumaOffset(coords, 1.0, -1.0);

