    let randomVec = vec3<f32>(getKernelRotation(vec2<f32>(in.position.x, uObject.uTexSize.y - in.position.y)), 0.0);
    let tangent = normalize(randomVec - selfViewNormal * dot(randomVec, selfViewNormal));
